import { z } from 'zod';
import { hhmm, isoDate, minutesFromHhmm, optionalText } from './primitives';

export const ATTENDANCE_STATUSES = ['PRESENT', 'ABSENT', 'LATE', 'EXCUSED'] as const;
export type AttendanceStatus = (typeof ATTENDANCE_STATUSES)[number];

/**
 * One register submission. `operationId` is generated by the client once per submission
 * and reused on every retry, so replays are applied at most once (ATT-009/010, §10.3).
 * `baseVersion` is the register version the client last saw; a mismatch is a conflict.
 */
export const attendanceSubmitSchema = z.object({
  operationId: z.uuid(),
  classId: z.uuid(),
  date: isoDate,
  slot: z.string().trim().min(1).max(40).default('DAY'),
  baseVersion: z.number().int().min(0).optional(),
  /** Required when changing marks already recorded (ATT-005). */
  correctionReason: optionalText(500),
  records: z
    .array(
      z.object({
        studentId: z.uuid(),
        status: z.enum(ATTENDANCE_STATUSES),
        arrivalTime: hhmm.optional(),
        reason: optionalText(300),
      }),
    )
    .min(1)
    .max(200),
});
export type AttendanceSubmitInput = z.infer<typeof attendanceSubmitSchema>;

export const roomSchema = z.object({
  campusId: z.uuid(),
  code: z.string().trim().min(1).max(20),
  name: z.string().trim().min(1).max(100),
  capacity: z.number().int().min(1).max(2000).optional(),
});
export type RoomInput = z.infer<typeof roomSchema>;

export const timetableEntrySchema = z
  .object({
    academicYearId: z.uuid(),
    classId: z.uuid(),
    subjectLabel: z.string().trim().min(1).max(80),
    staffId: z.uuid().optional(),
    roomId: z.uuid().optional(),
    weekday: z.number().int().min(1).max(7),
    startTime: hhmm,
    endTime: hhmm,
  })
  .refine((v) => minutesFromHhmm(v.endTime) > minutesFromHhmm(v.startTime), {
    message: 'end_before_start',
    path: ['endTime'],
  });
export type TimetableEntryInput = z.infer<typeof timetableEntrySchema>;
